def bounce(grid):
 out=[r[:] for r in grid]; ones=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==1]
 r,c=max(ones); dr=1
 while c+1<len(grid[0]):
  nr=r+dr; nc=c+1
  if nr<0 or nr>=len(grid) or grid[nr][nc]==2:
   dr=-dr; nr=r+dr
   if nr<0 or nr>=len(grid) or grid[nr][nc]==2: break
  r,c=nr,nc;out[r][c]=1
 return out
for i,p in enumerate(pairs):
 pred=bounce(p['input']); dif=[(r,c,pred[r][c],p['output'][r][c]) for r in range(16) for c in range(16) if pred[r][c]!=p['output'][r][c]]
 print(i,len(dif),dif[:15])

